package com.example.yikupayloadexample.util

import android.content.Context
import android.util.Log
import java.io.File
import java.io.FileOutputStream
import java.io.IOException

class AudioFileSaver(context: Context) {
    private val storageDir = context.getExternalFilesDir("radio_debug")
    private val outputFile = File(storageDir, "combined_data.raw") // 统一文件名

    init {
        if (!outputFile.exists()) {
            outputFile.createNewFile() // 首次创建文件
        }
    }

    // 追加字节数据到文件末尾
    fun appendByteArray(data: ByteArray) {
        try {
            FileOutputStream(outputFile, true).use { fos -> // true 表示追加模式
                fos.write(data)
            }
            Log.d("FileSaver", "数据已追加至文件: ${outputFile.absolutePath}")
        } catch (e: IOException) {
            Log.e("FileSaver", "追加失败", e)
        }
    }

    fun readInternalFile(context: Context): ByteArray? {
        val file = File(context.getExternalFilesDir("radio_read"), "combined_data.raw")
        return if (file.exists()) {
            file.readBytes()
        } else {
            Log.e("FileSaver", "文件不存在: ${file.absolutePath}")
            null
        }
    }

