        val listOfByteArrays: List<ByteArray> = hexStrings.map { hexString ->
            // 移除字符串中的分隔符 " "
            val cleanHex = hexString.replace(" ", "")
            // 确保字符串长度为偶数
            require(cleanHex.length % 2 == 0) { "Invalid hex string length" }

            // 将字符串每两个字符一组，转换为 Byte
            cleanHex.chunked(2).map { hexByte ->
                // 将十六进制字符串（如 "5B"）转换为 Byte
                hexByte.toInt(16).toByte()
            }.toByteArray() // 将这一组 Byte 列表转换为 ByteArray
        }
        return listOfByteArrays
